"""Assembles the SPIR-V shaders of the 2D renderer into code_runtime/source/shaders.inc.

The shaders are tiny, so they are assembled directly instead of requiring a GLSL compiler to build the project. The
equivalent GLSL is given next to each shader.

Usage: generate_shaders.py <output.inc>
"""
import struct
import sys

# Opcodes
OP = dict(
    Name=5, MemoryModel=14, EntryPoint=15, ExecutionMode=16, Capability=17,
    TypeVoid=19, TypeInt=21, TypeFloat=22, TypeVector=23, TypeImage=25, TypeSampledImage=27, TypeStruct=30,
    TypePointer=32, TypeFunction=33, Constant=43, ConstantComposite=44, Function=54, FunctionEnd=56, Variable=59,
    Load=61, Store=62, AccessChain=65, Decorate=71, MemberDecorate=72, CompositeConstruct=80, CompositeExtract=81,
    ImageSampleImplicitLod=87, FSub=131, FMul=133, Label=248, Return=253,
    ExtInstImport=11, ExtInst=12, TypeMatrix=24, TypeArray=28, VectorShuffle=79, FNegate=127, FAdd=129, FDiv=136,
    TypeBool=20, TypeRuntimeArray=29, FOrdLessThan=184, LogicalAnd=167, LogicalNot=168, SelectionMerge=247, BranchConditional=250, Kill=252,
    VectorTimesScalar=142, MatrixTimesVector=145, Dot=148, ConvertSToF=111, ConvertFToS=110,
    Image=100, ImageFetch=95, ImageRead=98, Phi=245, Branch=249, FOrdGreaterThan=186, SpecConstantTrue=48, SpecConstant=50,
    Extension=10, ImageWrite=99, BeginInvocationInterlockEXT=5364, EndInvocationInterlockEXT=5365,
    IAdd=128, Select=169, SLessThan=177, FOrdGreaterThanEqual=190,
    FOrdEqual=180, FOrdLessThanEqual=188, LogicalOr=166, DPdx=207, DPdy=208,
)
STORAGE = dict(UniformConstant=0, Input=1, Uniform=2, Output=3, PushConstant=9)
EXECUTION_MODEL_GLCOMPUTE, EXECUTION_MODE_LOCAL_SIZE = 5, 17
BUILTIN_WORKGROUP_ID, BUILTIN_LOCAL_INVOCATION_ID = 26, 27
DECORATION = dict(Block=2, BufferBlock=3, ColMajor=5, ArrayStride=6, MatrixStride=7, BuiltIn=11, Flat=14, NonWritable=24, Location=30, Binding=33, DescriptorSet=34, Offset=35, SpecId=1, InputAttachmentIndex=43, Coherent=23)
BUILTIN_INSTANCE_INDEX = 43
BUILTIN_FRAG_COORD = 15


def string_words(text):
    data = text.encode("utf-8") + b"\0"
    data += b"\0" * (-len(data) % 4)
    return list(struct.unpack("<%dI" % (len(data) // 4), data))


def float_bits(value):
    return struct.unpack("<I", struct.pack("<f", value))[0]


class Module:
    def __init__(self):
        self.next_id = 1
        self.header = []   # Capabilities, memory model, entry points, execution modes
        self.names = []
        self.annotations = []
        self.types = []    # Types, constants and global variables
        self.code = []

    def id(self):
        i = self.next_id
        self.next_id += 1
        return i

    @staticmethod
    def inst(op, *operands):
        words = []
        for operand in operands:
            if isinstance(operand, list):
                words.extend(operand)
            else:
                words.append(operand)
        return [((len(words) + 1) << 16) | OP[op]] + words

    def assemble(self):
        words = [0x07230203, 0x00010000, 0, self.next_id, 0]
        for part in (self.header, self.names, self.annotations, self.types, self.code):
            for inst in part:
                words.extend(inst)
        return words


def vertex_shader():
    """
    #version 450
    layout(location = 0) in vec2 inPosition;
    layout(location = 1) in vec2 inUV;
    layout(location = 2) in vec4 inColor;
    layout(push_constant) uniform Constants { vec2 scale; } pc; // 1 / size of the target in pixels
    layout(location = 0) out vec2 outUV;
    layout(location = 1) out vec4 outColor;
    void main() {
        vec2 p = inPosition * pc.scale * 2.0 - 1.0;
        gl_Position = vec4(p.x, p.y, 0.0, 1.0);
        gl_PointSize = 1.0;
        outUV = inUV;
        outColor = inColor;
    }
    """
    m = Module()
    i = m.inst
    void, fn, flt, vec2, vec4, int_ = m.id(), m.id(), m.id(), m.id(), m.id(), m.id()
    pv_struct, pc_struct = m.id(), m.id()
    p_in_v2, p_in_v4, p_out_v2, p_out_v4, p_out_pv, p_pc, p_pc_v2, p_out_v4b, p_out_f = (m.id() for _ in range(9))
    c_int0, c_int1, c_f0, c_f1, c_f2, c_v2_two, c_v2_one = (m.id() for _ in range(7))
    in_pos, in_uv, in_color, out_uv, out_color, pv_var, pc_var = (m.id() for _ in range(7))
    main, label = m.id(), m.id()

    m.header += [
        i("Capability", 1),                       # Shader
        i("MemoryModel", 0, 1),                   # Logical, GLSL450
        i("EntryPoint", 0, main, string_words("main"), in_pos, in_uv, in_color, out_uv, out_color, pv_var),
    ]
    m.names += [i("Name", main, string_words("main"))]
    m.annotations += [
        i("Decorate", in_pos, DECORATION["Location"], 0),
        i("Decorate", in_uv, DECORATION["Location"], 1),
        i("Decorate", in_color, DECORATION["Location"], 2),
        i("Decorate", out_uv, DECORATION["Location"], 0),
        i("Decorate", out_color, DECORATION["Location"], 1),
        i("MemberDecorate", pv_struct, 0, DECORATION["BuiltIn"], 0),   # Position
        i("MemberDecorate", pv_struct, 1, DECORATION["BuiltIn"], 1),   # PointSize
        i("Decorate", pv_struct, DECORATION["Block"]),
        i("MemberDecorate", pc_struct, 0, DECORATION["Offset"], 0),
        i("Decorate", pc_struct, DECORATION["Block"]),
    ]
    m.types += [
        i("TypeVoid", void),
        i("TypeFunction", fn, void),
        i("TypeFloat", flt, 32),
        i("TypeVector", vec2, flt, 2),
        i("TypeVector", vec4, flt, 4),
        i("TypeInt", int_, 32, 1),
        i("TypeStruct", pv_struct, vec4, flt),
        i("TypeStruct", pc_struct, vec2),
        i("TypePointer", p_in_v2, STORAGE["Input"], vec2),
        i("TypePointer", p_in_v4, STORAGE["Input"], vec4),
        i("TypePointer", p_out_v2, STORAGE["Output"], vec2),
        i("TypePointer", p_out_v4, STORAGE["Output"], vec4),
        i("TypePointer", p_out_pv, STORAGE["Output"], pv_struct),
        i("TypePointer", p_pc, STORAGE["PushConstant"], pc_struct),
        i("TypePointer", p_pc_v2, STORAGE["PushConstant"], vec2),
        i("TypePointer", p_out_f, STORAGE["Output"], flt),
        i("Constant", int_, c_int0, 0),
        i("Constant", int_, c_int1, 1),
        i("Constant", flt, c_f0, float_bits(0.0)),
        i("Constant", flt, c_f1, float_bits(1.0)),
        i("Constant", flt, c_f2, float_bits(2.0)),
        i("ConstantComposite", vec2, c_v2_two, c_f2, c_f2),
        i("ConstantComposite", vec2, c_v2_one, c_f1, c_f1),
        i("Variable", p_in_v2, in_pos, STORAGE["Input"]),
        i("Variable", p_in_v2, in_uv, STORAGE["Input"]),
        i("Variable", p_in_v4, in_color, STORAGE["Input"]),
        i("Variable", p_out_v2, out_uv, STORAGE["Output"]),
        i("Variable", p_out_v4, out_color, STORAGE["Output"]),
        i("Variable", p_out_pv, pv_var, STORAGE["Output"]),
        i("Variable", p_pc, pc_var, STORAGE["PushConstant"]),
    ]

    pos, scale_ptr, scale, scaled, doubled, shifted, x, y, position = (m.id() for _ in range(9))
    pos_ptr, size_ptr, uv, color = m.id(), m.id(), m.id(), m.id()
    m.code += [
        i("Function", void, main, 0, fn),
        i("Label", label),
        i("Load", vec2, pos, in_pos),
        i("AccessChain", p_pc_v2, scale_ptr, pc_var, c_int0),
        i("Load", vec2, scale, scale_ptr),
        i("FMul", vec2, scaled, pos, scale),
        i("FMul", vec2, doubled, scaled, c_v2_two),
        i("FSub", vec2, shifted, doubled, c_v2_one),
        i("CompositeExtract", flt, x, shifted, 0),
        i("CompositeExtract", flt, y, shifted, 1),
        i("CompositeConstruct", vec4, position, x, y, c_f0, c_f1),
        i("AccessChain", p_out_v4, pos_ptr, pv_var, c_int0),
        i("Store", pos_ptr, position),
        i("AccessChain", p_out_f, size_ptr, pv_var, c_int1),
        i("Store", size_ptr, c_f1),
        i("Load", vec2, uv, in_uv),
        i("Store", out_uv, uv),
        i("Load", vec4, color, in_color),
        i("Store", out_color, color),
        i("Return"),
        i("FunctionEnd"),
    ]
    return m.assemble()


def fragment_shader():
    """
    #version 450
    layout(set = 0, binding = 0) uniform sampler2D tex;
    layout(location = 0) in vec2 inUV;
    layout(location = 1) in vec4 inColor;
    layout(location = 0) out vec4 outColor;
    void main() {
        outColor = inColor * texture(tex, inUV);
    }
    """
    m = Module()
    i = m.inst
    void, fn, flt, vec2, vec4 = m.id(), m.id(), m.id(), m.id(), m.id()
    image, sampled, p_uc, p_in_v2, p_in_v4, p_out_v4 = (m.id() for _ in range(6))
    tex, in_uv, in_color, out_color = (m.id() for _ in range(4))
    main, label = m.id(), m.id()

    m.header += [
        i("Capability", 1),
        i("MemoryModel", 0, 1),
        i("EntryPoint", 4, main, string_words("main"), in_uv, in_color, out_color),
        i("ExecutionMode", main, 7),              # OriginUpperLeft
    ]
    m.names += [i("Name", main, string_words("main"))]
    m.annotations += [
        i("Decorate", in_uv, DECORATION["Location"], 0),
        i("Decorate", in_color, DECORATION["Location"], 1),
        i("Decorate", out_color, DECORATION["Location"], 0),
        i("Decorate", tex, DECORATION["DescriptorSet"], 0),
        i("Decorate", tex, DECORATION["Binding"], 0),
    ]
    m.types += [
        i("TypeVoid", void),
        i("TypeFunction", fn, void),
        i("TypeFloat", flt, 32),
        i("TypeVector", vec2, flt, 2),
        i("TypeVector", vec4, flt, 4),
        i("TypeImage", image, flt, 1, 0, 0, 0, 1, 0),   # 2D, not depth, not arrayed, single sampled, sampled, unknown format
        i("TypeSampledImage", sampled, image),
        i("TypePointer", p_uc, STORAGE["UniformConstant"], sampled),
        i("TypePointer", p_in_v2, STORAGE["Input"], vec2),
        i("TypePointer", p_in_v4, STORAGE["Input"], vec4),
        i("TypePointer", p_out_v4, STORAGE["Output"], vec4),
        i("Variable", p_uc, tex, STORAGE["UniformConstant"]),
        i("Variable", p_in_v2, in_uv, STORAGE["Input"]),
        i("Variable", p_in_v4, in_color, STORAGE["Input"]),
        i("Variable", p_out_v4, out_color, STORAGE["Output"]),
    ]

    uv, color, image_value, sample, result = (m.id() for _ in range(5))
    m.code += [
        i("Function", void, main, 0, fn),
        i("Label", label),
        i("Load", vec2, uv, in_uv),
        i("Load", vec4, color, in_color),
        i("Load", sampled, image_value, tex),
        i("ImageSampleImplicitLod", vec4, sample, image_value, uv),
        i("FMul", vec4, result, color, sample),
        i("Store", out_color, result),
        i("Return"),
        i("FunctionEnd"),
    ]
    return m.assemble()


class Builder:
    """Small helper for straight-line shader code: types and constants are created (and shared) on demand."""

    def __init__(self):
        self.m = Module()
        self.cache = {}
        self.glsl = self.m.id()
        self.m.header.append(Module.inst("Capability", 1))
        self.m.header.append(Module.inst("ExtInstImport", self.glsl, string_words("GLSL.std.450")))
        self.m.header.append(Module.inst("MemoryModel", 0, 1))

    def new_type(self, key, op, *operands):
        if key not in self.cache:
            i = self.m.id()
            self.cache[key] = i
            self.m.types.append(Module.inst(op, i, *operands))
        return self.cache[key]

    def void(self): return self.new_type("void", "TypeVoid")
    def float(self): return self.new_type("float", "TypeFloat", 32)
    def int(self): return self.new_type("int", "TypeInt", 32, 1)
    def vec(self, n): return self.new_type(("vec", n), "TypeVector", self.float(), n)
    def mat4(self): return self.new_type("mat4", "TypeMatrix", self.vec(4), 4)
    def fn(self): return self.new_type("fn", "TypeFunction", self.void())

    def array(self, element, count, name):
        return self.new_type(("array", name), "TypeArray", element, self.const_int(count))

    def struct(self, name, *members):
        return self.new_type(("struct", name), "TypeStruct", *members)

    def pointer(self, storage, target):
        return self.new_type(("ptr", storage, target), "TypePointer", STORAGE[storage], target)

    def const_float(self, value):
        key = ("f", float_bits(value))
        if key not in self.cache:
            i = self.m.id()
            self.cache[key] = i
            self.m.types.append(Module.inst("Constant", self.float(), i, float_bits(value)))
        return self.cache[key]

    def const_int(self, value):
        key = ("i", value)
        if key not in self.cache:
            i = self.m.id()
            self.cache[key] = i
            self.m.types.append(Module.inst("Constant", self.int(), i, value & 0xFFFFFFFF))
        return self.cache[key]

    def const_vec(self, n, value):
        key = ("v", n, float_bits(value))
        if key not in self.cache:
            i = self.m.id()
            self.cache[key] = i
            c = self.const_float(value)
            self.m.types.append(Module.inst("ConstantComposite", self.vec(n), i, *([c] * n)))
        return self.cache[key]

    def variable(self, storage, target, decorations=()):
        i = self.m.id()
        self.m.types.append(Module.inst("Variable", self.pointer(storage, target), i, STORAGE[storage]))
        for decoration in decorations:
            self.m.annotations.append(Module.inst("Decorate", i, *decoration))
        return i

    def emit(self, op, result_type, *operands):
        i = self.m.id()
        self.m.code.append(Module.inst(op, result_type, i, *operands))
        return i

    def load(self, type_id, pointer): return self.emit("Load", type_id, pointer)
    def store(self, pointer, value): self.m.code.append(Module.inst("Store", pointer, value))
    def access(self, storage, target, base, *indices): return self.emit("AccessChain", self.pointer(storage, target), base, *indices)
    def extract(self, composite, index): return self.emit("CompositeExtract", self.float(), composite, index)
    def construct(self, n, *parts): return self.emit("CompositeConstruct", self.vec(n), *parts)
    def swizzle(self, vector, n): return self.emit("VectorShuffle", self.vec(n), vector, vector, *range(n))
    def ext(self, type_id, number, *operands): return self.emit("ExtInst", type_id, self.glsl, number, *operands)
    def fadd(self, t, a, b): return self.emit("FAdd", t, a, b)
    def fsub(self, t, a, b): return self.emit("FSub", t, a, b)
    def fmul(self, t, a, b): return self.emit("FMul", t, a, b)
    def fdiv(self, t, a, b): return self.emit("FDiv", t, a, b)
    def scale(self, n, vector, scalar): return self.emit("VectorTimesScalar", self.vec(n), vector, scalar)
    def dot(self, a, b): return self.emit("Dot", self.float(), a, b)


# GLSL.std.450 instruction numbers
GLSL_FABS, GLSL_POW, GLSL_STEP = 4, 26, 48
GLSL_FLOOR, GLSL_FRACT = 8, 10
GLSL_FMAX, GLSL_FCLAMP, GLSL_LENGTH = 40, 43, 66
GLSL_SQRT, GLSL_FMIN = 31, 37
GLSL_EXP2, GLSL_LOG2, GLSL_FMIX = 29, 30, 46


# The lights of a camera that entities pick eight of (max_lights in graphics_internal.hpp), after the rest of the block.
MAX_LIGHTS = 128
SCENE_LIGHTS = 176
# Members of the entity_push of graphics_internal.hpp (all vec4): 3 rows of the model, material, params, uv, mask, extra, texgen, lights, soft, and three for the views of atlases.
ENTITY_MEMBERS = 14


def declare_scene(b):
    """The block that holds what is the same for everything a camera draws, see scene_data in graphics.cpp."""
    v4 = b.vec(4)
    lights = b.array(v4, MAX_LIGHTS, "lights")
    scene = b.struct("scene", b.mat4(), v4, lights, lights, v4, v4, v4, lights, v4, v4, v4, v4)
    b.m.annotations += [
        Module.inst("MemberDecorate", scene, 0, DECORATION["Offset"], 0),
        Module.inst("MemberDecorate", scene, 0, DECORATION["ColMajor"]),
        Module.inst("MemberDecorate", scene, 0, DECORATION["MatrixStride"], 16),
        Module.inst("MemberDecorate", scene, 1, DECORATION["Offset"], 64),
        Module.inst("MemberDecorate", scene, 2, DECORATION["Offset"], SCENE_LIGHTS),  # The table of lights is last, and entities pick from it.
        Module.inst("MemberDecorate", scene, 3, DECORATION["Offset"], SCENE_LIGHTS + MAX_LIGHTS * 16),
        Module.inst("MemberDecorate", scene, 4, DECORATION["Offset"], 80),
        Module.inst("MemberDecorate", scene, 5, DECORATION["Offset"], 96),
        Module.inst("MemberDecorate", scene, 6, DECORATION["Offset"], 112),
        Module.inst("MemberDecorate", scene, 7, DECORATION["Offset"], SCENE_LIGHTS + MAX_LIGHTS * 32),
        Module.inst("MemberDecorate", scene, 8, DECORATION["Offset"], 128),  # The axes of the camera, to find camera space.
        Module.inst("MemberDecorate", scene, 9, DECORATION["Offset"], 144),
        Module.inst("MemberDecorate", scene, 10, DECORATION["Offset"], 160),
        Module.inst("MemberDecorate", scene, 11, DECORATION["Offset"], SCENE_LIGHTS + MAX_LIGHTS * 48),  # Near, far and whether orthographic, to turn depth back into distance.
        Module.inst("Decorate", lights, DECORATION["ArrayStride"], 16),
        Module.inst("Decorate", scene, DECORATION["Block"]),
    ]
    return b.variable("Uniform", scene, [(DECORATION["DescriptorSet"], 1), (DECORATION["Binding"], 0)])


def declare_entities(b, set_index=2):
    """
    What differs for each draw: the entity_push of graphics_internal.hpp, one for each instance in a buffer that is read
    with the index of the instance, which is where the draw call says it starts (firstInstance) plus the number of the
    instance. This is not a push constant so that many draws of the same thing can be one call.
    Returns the variable of the buffer.
    """
    v4 = b.vec(4)
    entity = b.struct("entity", *([v4] * ENTITY_MEMBERS))
    for index in range(ENTITY_MEMBERS):
        b.m.annotations.append(Module.inst("MemberDecorate", entity, index, DECORATION["Offset"], index * 16))
    entities = b.new_type("entities", "TypeRuntimeArray", entity)
    b.m.annotations.append(Module.inst("Decorate", entities, DECORATION["ArrayStride"], ENTITY_MEMBERS * 16))
    block = b.struct("entity_block", entities)
    b.m.annotations += [
        Module.inst("MemberDecorate", block, 0, DECORATION["Offset"], 0),
        Module.inst("MemberDecorate", block, 0, DECORATION["NonWritable"]),
        Module.inst("Decorate", block, DECORATION["BufferBlock"]),
    ]
    return b.variable("Uniform", block, [(DECORATION["DescriptorSet"], set_index), (DECORATION["Binding"], 0)]), entity


def entity_member(b, entities, instance, index):
    return b.load(b.vec(4), b.access("Uniform", b.vec(4), entities, b.const_int(0), instance, b.const_int(index)))


def vertex_shader_3d():
    """
    Lit the way Blitz3D (fixed function) does: per vertex, ambient plus up to 8 directional or point lights, which are
    the eight that are nearest to the draw out of the table of the camera (entity.lights picks them).

    #version 450
    layout(location = 0) in vec3 inPosition;
    layout(location = 1) in vec3 inNormal;
    layout(location = 2) in vec2 inUV;
    layout(location = 3) in vec4 inColor;
    layout(location = 4) in vec2 inUV2;
    layout(set = 1, binding = 0) uniform Scene {
        mat4 viewProjection;
        vec4 ambient;
        vec4 lightPosition[8];   // Direction towards the light if w == 0, position and range (w) otherwise.
        vec4 lightColor[8];
        vec4 fog;                // Near, far and whether it is on.
        vec4 fogColor;
        vec4 eye;                // Where the camera is.
        vec4 lightDirection[8];  // Where a spot light shines to, and the cosine of half its outer angle (below -1 if not a spot).
    } scene;
    struct Entity {
        vec4 model0, model1, model2; // Rows of the 4x3 model matrix.
        vec4 material;               // Color and alpha of the entity.
        vec4 params;                 // x: fullbright, y: vertex color, z: vertex alpha, w: shininess
        vec4 uv;                     // Scale (x, y) and offset (z, w) of the texture coordinates.
        vec4 mask;                   // For the fragment shader.
        vec4 extra;                  // x: whether the second set of texture coordinates is used, y and z: sine and cosine minus one of RotateTexture.
        vec4 texgen;                 // x: 1 for a sphere map, 2 for a cube map. y: what a cube map shows (1 reflection, 2 normal, 3 position), z: whether in camera space, w: half a texel of a face.
    };
    layout(set = 2, binding = 0) readonly buffer Entities { Entity entities[]; };
    #define entity entities[gl_InstanceIndex]
    layout(location = 6) flat out vec4 outMask; // What the fragment shader needs of the entity, so that it does not read the buffer.
    layout(location = 8) flat out vec4 outSoft; // x: the distance of SpriteDepthFade, 0 if off.
    layout(location = 0) out vec2 outUV;
    layout(location = 1) out vec4 outColor;
    void main() {
        vec4 p = vec4(inPosition, 1.0);
        vec3 world = vec3(dot(entity.model0, p), dot(entity.model1, p), dot(entity.model2, p));
        vec3 n = normalize(vec3(dot(entity.model0.xyz, inNormal), dot(entity.model1.xyz, inNormal), dot(entity.model2.xyz, inNormal)));
        gl_Position = scene.viewProjection * vec4(world, 1.0);
        vec3 lit = scene.ambient.xyz;
        for (int i = 0; i < 8; i++) {
            float isPoint = clamp(scene.lightPosition[i].w * 1000.0, 0.0, 1.0);
            vec3 delta = scene.lightPosition[i].xyz - world;
            float dist = length(delta);
            vec3 direction = mix(scene.lightPosition[i].xyz, delta / max(dist, 1e-4), isPoint);
            float falloff = scene.lightPosition[i].w / max(dist, 1e-4);
            lit += scene.lightColor[i].xyz * max(dot(n, direction), 0.0) * mix(1.0, falloff, isPoint);
        }
        lit = mix(lit, vec3(1.0), entity.params.x);
        outColor = vec4(clamp(entity.material.xyz * inColor.xyz * lit, 0.0, 1.0), entity.material.w * inColor.w);
        outUV = inUV;
    }
    """
    b = Builder()
    f, v2, v3, v4 = b.float(), b.vec(2), b.vec(3), b.vec(4)
    void, fn = b.void(), b.fn()
    c0, c1 = b.const_float(0.0), b.const_float(1.0)

    ubo = declare_scene(b)

    # What differs for each draw
    entities, _ = declare_entities(b)
    in_instance = b.variable("Input", b.int(), [(DECORATION["BuiltIn"], BUILTIN_INSTANCE_INDEX)])
    out_mask = b.variable("Output", b.vec(4), [(DECORATION["Location"], 6), (DECORATION["Flat"],)])
    out_soft = b.variable("Output", b.vec(4), [(DECORATION["Location"], 8), (DECORATION["Flat"],)])
    out_views = [b.variable("Output", b.vec(4), [(DECORATION["Location"], 9 + k), (DECORATION["Flat"],)]) for k in range(3)]  # Views of atlases, see view_sample.

    # Inputs and outputs
    in_pos = b.variable("Input", v3, [(DECORATION["Location"], 0)])
    in_normal = b.variable("Input", v3, [(DECORATION["Location"], 1)])
    in_uv = b.variable("Input", v2, [(DECORATION["Location"], 2)])
    in_color = b.variable("Input", v4, [(DECORATION["Location"], 3)])
    in_uv2 = b.variable("Input", v2, [(DECORATION["Location"], 4)])
    out_uv = b.variable("Output", v2, [(DECORATION["Location"], 0)])
    out_dir = b.variable("Output", v4, [(DECORATION["Location"], 7)])  # Cube maps: where to look, and the inset of a face (0 if not a cube map).
    out_color = b.variable("Output", v4, [(DECORATION["Location"], 1)])
    out_depth = b.variable("Output", f, [(DECORATION["Location"], 2)])
    out_color_flat = b.variable("Output", v4, [(DECORATION["Location"], 3), (DECORATION["Flat"],)])
    out_spec = b.variable("Output", v3, [(DECORATION["Location"], 4)])
    out_spec_flat = b.variable("Output", v3, [(DECORATION["Location"], 5), (DECORATION["Flat"],)])
    per_vertex = b.struct("pervertex", v4, f)
    b.m.annotations += [
        Module.inst("MemberDecorate", per_vertex, 0, DECORATION["BuiltIn"], 0),
        Module.inst("MemberDecorate", per_vertex, 1, DECORATION["BuiltIn"], 1),
        Module.inst("Decorate", per_vertex, DECORATION["Block"]),
    ]
    out_vertex = b.variable("Output", per_vertex)

    main, label = b.m.id(), b.m.id()
    b.m.header.append(Module.inst("EntryPoint", 0, main, string_words("main"), in_pos, in_normal, in_uv, in_color, in_uv2, out_uv, out_color, out_depth, out_color_flat, out_spec, out_spec_flat, out_vertex, in_instance, out_mask, out_dir, out_soft, *out_views))
    b.m.names.append(Module.inst("Name", main, string_words("main")))
    b.m.code += [Module.inst("Function", void, main, 0, fn), Module.inst("Label", label)]

    instance = b.load(b.int(), in_instance)
    b.store(out_mask, entity_member(b, entities, instance, 6))
    b.store(out_soft, entity_member(b, entities, instance, 10))
    for k in range(3):
        b.store(out_views[k], entity_member(b, entities, instance, 11 + k))

    def push_member(index):
        return entity_member(b, entities, instance, index)

    pos, normal = b.load(v3, in_pos), b.load(v3, in_normal)
    color = b.load(v4, in_color)
    row0, row1, row2, material, params, uvparams = (push_member(i) for i in range(6))
    extra = push_member(7)
    texgen = push_member(8)

    p4 = b.construct(4, b.extract(pos, 0), b.extract(pos, 1), b.extract(pos, 2), c1)
    world = b.construct(3, b.dot(row0, p4), b.dot(row1, p4), b.dot(row2, p4))
    r0, r1, r2 = b.swizzle(row0, 3), b.swizzle(row1, 3), b.swizzle(row2, 3)
    nw = b.construct(3, b.dot(r0, normal), b.dot(r1, normal), b.dot(r2, normal))
    n_len = b.ext(f, GLSL_LENGTH, nw)
    n = b.scale(3, nw, b.fdiv(f, c1, b.ext(f, GLSL_FMAX, n_len, b.const_float(1e-6))))

    vp = b.load(b.mat4(), b.access("Uniform", b.mat4(), ubo, b.const_int(0)))
    world4 = b.construct(4, b.extract(world, 0), b.extract(world, 1), b.extract(world, 2), c1)
    clip = b.emit("MatrixTimesVector", v4, vp, world4)
    b.store(b.access("Output", v4, out_vertex, b.const_int(0)), clip)
    b.store(b.access("Output", f, out_vertex, b.const_int(1)), c1)

    lit = b.swizzle(b.load(v4, b.access("Uniform", v4, ubo, b.const_int(1))), 3)
    ones, zeros = b.const_vec(3, 1.0), b.const_vec(3, 0.0)
    eye = b.swizzle(b.load(v4, b.access("Uniform", v4, ubo, b.const_int(6))), 3)
    to_eye = b.fsub(v3, eye, world)
    view = b.scale(3, to_eye, b.fdiv(f, c1, b.ext(f, GLSL_FMAX, b.ext(f, GLSL_LENGTH, to_eye), b.const_float(1e-4))))
    shininess = b.extract(params, 3)
    power = b.ext(f, GLSL_FMAX, b.fmul(f, shininess, b.const_float(128.0)), b.const_float(1e-3))
    specular = zeros
    # The eight lights of this draw: entity.lights holds their places in the table, two to a float (even + 256 * odd).
    packed = push_member(9)
    chosen = []
    for pair in range(4):
        both = b.extract(packed, pair)
        high = b.ext(f, GLSL_FLOOR, b.fmul(f, both, b.const_float(1.0 / 256.0)))
        chosen.append(b.emit("ConvertFToS", b.int(), b.fsub(f, both, b.fmul(f, high, b.const_float(256.0)))))
        chosen.append(b.emit("ConvertFToS", b.int(), high))
    for light in range(8):
        lp = b.load(v4, b.access("Uniform", v4, ubo, b.const_int(2), chosen[light]))
        lc = b.load(v4, b.access("Uniform", v4, ubo, b.const_int(3), chosen[light]))
        ld = b.load(v4, b.access("Uniform", v4, ubo, b.const_int(7), chosen[light]))
        lpos, w = b.swizzle(lp, 3), b.extract(lp, 3)
        delta = b.fsub(v3, lpos, world)
        dist = b.ext(f, GLSL_LENGTH, delta)
        to_point = b.scale(3, delta, b.fdiv(f, c1, b.ext(f, GLSL_FMAX, dist, b.const_float(1e-4))))
        is_point = b.ext(f, GLSL_FCLAMP, b.fmul(f, w, b.const_float(1000.0)), c0, c1)
        direction = b.fadd(v3, b.scale(3, lpos, b.fsub(f, c1, is_point)), b.scale(3, to_point, is_point))
        ndotl = b.ext(f, GLSL_FMAX, b.dot(n, direction), c0)
        range_ = b.ext(f, GLSL_FMAX, w, b.const_float(1e-4))
        # Direct3D 7 attenuation 1 / (a1 * d) with a1 = 1 / range, which is range / d: it is not clamped and is above one close by.
        falloff = b.fdiv(f, range_, b.ext(f, GLSL_FMAX, dist, b.const_float(1e-4)))
        attenuation = b.fadd(f, c1, b.fmul(f, b.fsub(f, falloff, c1), is_point))
        # Spot lights fade between the cosines of the half angles of the cone: ld.w is the outer and lc.w the inner one,
        # and ld.w is below -1 for lights that are not spots.
        rho = b.fsub(f, c0, b.dot(direction, b.swizzle(ld, 3)))
        cone_span = b.ext(f, GLSL_FMAX, b.fsub(f, b.extract(lc, 3), b.extract(ld, 3)), b.const_float(1e-4))
        cone = b.ext(f, GLSL_FCLAMP, b.fdiv(f, b.fsub(f, rho, b.extract(ld, 3)), cone_span), c0, c1)
        is_spot = b.ext(f, GLSL_STEP, b.const_float(-1.5), b.extract(ld, 3))
        spot = b.fadd(f, c1, b.fmul(f, b.fsub(f, cone, c1), is_spot))
        attenuation = b.fmul(f, attenuation, spot)
        contribution = b.scale(3, b.swizzle(lc, 3), b.fmul(f, ndotl, attenuation))
        lit = b.fadd(v3, lit, contribution)
        # Blinn-Phong with the viewer where the camera is, and the light itself white.
        half = b.fadd(v3, direction, view)
        half = b.scale(3, half, b.fdiv(f, c1, b.ext(f, GLSL_FMAX, b.ext(f, GLSL_LENGTH, half), b.const_float(1e-4))))
        ndoth = b.ext(f, GLSL_FMAX, b.dot(n, half), b.const_float(1e-4))
        facing = b.ext(f, GLSL_STEP, b.const_float(1e-6), ndotl)
        highlight = b.fmul(f, b.fmul(f, b.ext(f, GLSL_POW, ndoth, power), facing), attenuation)
        specular = b.fadd(v3, specular, b.scale(3, ones, highlight))

    fullbright = b.extract(params, 0)
    lit = b.fadd(v3, lit, b.scale(3, b.fsub(v3, ones, lit), fullbright))
    strength = b.ext(f, GLSL_FCLAMP, shininess, c0, c1)
    specular = b.scale(3, specular, b.fmul(f, strength, b.fsub(f, c1, fullbright)))
    # The vertex color replaces the color of the entity if the effect says so, and only then does its alpha count.
    use_vertex_color, use_vertex_alpha = b.extract(params, 1), b.extract(params, 2)
    entity_rgb = b.swizzle(material, 3)
    vertex_rgb = b.swizzle(color, 3)
    base = b.fadd(v3, entity_rgb, b.scale(3, b.fsub(v3, vertex_rgb, entity_rgb), use_vertex_color))
    rgb = b.ext(v3, GLSL_FCLAMP, b.fmul(v3, base, lit), zeros, ones)

    vertex_alpha = b.fadd(f, c1, b.fmul(f, b.fsub(f, b.extract(color, 3), c1), use_vertex_alpha))
    entity_alpha = b.fmul(f, b.extract(material, 3), vertex_alpha)
    # With vertex colors Direct3D takes the whole diffuse color from the vertices, so the alpha of the entity is not used.
    alpha = b.fadd(f, entity_alpha, b.fmul(f, b.fsub(f, b.extract(color, 3), entity_alpha), use_vertex_color))
    final = b.construct(4, b.extract(rgb, 0), b.extract(rgb, 1), b.extract(rgb, 2), alpha)
    b.store(out_color, final)
    b.store(out_color_flat, final)
    b.store(out_spec, specular)
    b.store(out_spec_flat, specular)
    # Textures can be scaled and moved: the first two are factors, the last two offsets.
    uv_scale, uv_offset = b.swizzle(uvparams, 2), b.construct(2, b.extract(uvparams, 2), b.extract(uvparams, 3))
    first_uv, second_uv = b.load(v2, in_uv), b.load(v2, in_uv2)
    chosen_uv = b.fadd(v2, first_uv, b.scale(2, b.fsub(v2, second_uv, first_uv), b.extract(extra, 0)))
    # RotateTexture turns the coordinates first: extra.y is the sine and extra.z the cosine minus one, so that a texture that is not turned has zeros.
    sine, cosine = b.extract(extra, 1), b.fadd(f, b.extract(extra, 2), b.const_float(1.0))
    cu, cv = b.extract(chosen_uv, 0), b.extract(chosen_uv, 1)
    turned_u = b.fadd(f, b.fmul(f, cosine, cu), b.fmul(f, sine, cv))
    turned_v = b.fsub(f, b.fmul(f, cosine, cv), b.fmul(f, sine, cu))
    chosen_uv = b.construct(2, turned_u, turned_v)
    plain_uv = b.fadd(v2, b.fmul(v2, chosen_uv, uv_scale), uv_offset)
    # Environment maps make their own coordinates, as the fixed function pipeline of the original does.
    cam_right = b.swizzle(b.load(v4, b.access("Uniform", v4, ubo, b.const_int(8))), 3)
    cam_up = b.swizzle(b.load(v4, b.access("Uniform", v4, ubo, b.const_int(9))), 3)
    cam_forward = b.swizzle(b.load(v4, b.access("Uniform", v4, ubo, b.const_int(10))), 3)

    def to_camera(vector):
        return b.construct(3, b.dot(vector, cam_right), b.dot(vector, cam_up), b.dot(vector, cam_forward))

    half = b.const_float(0.5)
    normal_cam = to_camera(n)
    sphere_uv = b.construct(2, b.fadd(f, b.fmul(f, half, b.extract(normal_cam, 0)), half), b.fsub(f, half, b.fmul(f, half, b.extract(normal_cam, 1))))
    kind = b.extract(texgen, 0)
    is_sphere = b.fmul(f, b.ext(f, GLSL_STEP, half, kind), b.fsub(f, c1, b.ext(f, GLSL_STEP, b.const_float(1.5), kind)))
    is_cube = b.ext(f, GLSL_STEP, b.const_float(1.5), kind)
    b.store(out_uv, b.fadd(v2, plain_uv, b.scale(2, b.fsub(v2, sphere_uv, plain_uv), is_sphere)))
    incident_raw = b.fsub(v3, world, eye)
    incident = b.scale(3, incident_raw, b.fdiv(f, c1, b.ext(f, GLSL_FMAX, b.ext(f, GLSL_LENGTH, incident_raw), b.const_float(1e-4))))
    reflection = b.fsub(v3, incident, b.scale(3, n, b.fmul(f, b.const_float(2.0), b.dot(n, incident))))
    cube_mode = b.extract(texgen, 1)
    look = b.fadd(v3, reflection, b.scale(3, b.fsub(v3, n, reflection), b.ext(f, GLSL_STEP, b.const_float(1.5), cube_mode)))
    look = b.fadd(v3, look, b.scale(3, b.fsub(v3, incident_raw, look), b.ext(f, GLSL_STEP, b.const_float(2.5), cube_mode)))
    look = b.fadd(v3, look, b.scale(3, b.fsub(v3, to_camera(look), look), b.extract(texgen, 2)))
    b.store(out_dir, b.construct(4, b.extract(look, 0), b.extract(look, 1), b.extract(look, 2), b.fmul(f, b.extract(texgen, 3), is_cube)))
    b.store(out_depth, b.extract(clip, 3))  # For the fog, which the fragment shader takes care of.
    b.m.code += [Module.inst("Return"), Module.inst("FunctionEnd")]
    return b.m.assemble()




def view_sample(b, image, uv, ddx, ddy, v0, v1, v2):
    """
    What a view of an atlas reads (a tile that AtlasTexture or the runtime made, see texture_view in graphics_textures.cpp), the way a
    sampler would if it could wrap and mip inside a rectangle of an image: the tile is the rectangle (v0: x, y, width, height in texels of
    the first level, aligned so that level k is at the position divided by 2^k), the coordinates are the ones of the tile (0 to 1 is the
    tile), and the settings of the texture are in the other two values:
      v1.x = address mode of u (0 repeat, 1 mirror, 2 clamp, 3 border) + 4 * mode of v + 16 * linear magnification + 32 * linear minification
             + 64 * linear between mip levels + 128 * (levels - 1), v1.y, v1.z, v1.w: bias, lowest and highest level of detail; v2: the border color.
    Four texels are fetched from each of two levels and mixed by hand, with the wrapping done on the texel numbers, so that nothing from
    the next tile is ever read, whatever the mode is. `uv`, `ddx` and `ddy` are the coordinates and their derivatives (taken where all
    pixels of a quad agree on the branch, see the caller).

        vec4 view_sample(sampler2D tex, vec2 uv, vec2 ddx, vec2 ddy, vec4 v0, vec4 v1, vec4 v2) {
            vec2 size = v0.zw;
            float rho = max(length(ddx * size), length(ddy * size));
            float lod = log2(max(rho, 1e-8)) + v1.y;
            bool minify = lod > 0.0;
            float top = float(levels - 1);
            lod = clamp(lod, v1.z, min(v1.w, top));
            float l0 = floor(lod), l1 = min(l0 + 1.0, top), f = lod - l0;
            f = mipLinear ? f : step(0.5, f);
            return mix(tap(l0), tap(l1), f);        // tap: bilinear (or nearest) at one level, wrapped by texel number
        }
    """
    f, v2t, v4 = b.float(), b.vec(2), b.vec(4)
    boolean = b.new_type("bool", "TypeBool")
    iv2 = b.new_type("ivec2", "TypeVector", b.int(), 2)
    zero, one, half, two = b.const_float(0.0), b.const_float(1.0), b.const_float(0.5), b.const_float(2.0)

    def fmin(x, y): return b.ext(f, GLSL_FMIN, x, y)
    def fmax(x, y): return b.ext(f, GLSL_FMAX, x, y)
    def floor_(x): return b.ext(f, GLSL_FLOOR, x)
    def add(x, y): return b.fadd(f, x, y)
    def sub(x, y): return b.fsub(f, x, y)
    def mul(x, y): return b.fmul(f, x, y)
    def sel(cond, x, y): return b.emit("Select", f, cond, x, y)
    def eq(x, y): return b.emit("FOrdEqual", boolean, x, y)
    def lt(x, y): return b.emit("FOrdLessThan", boolean, x, y)
    def ge(x, y): return b.emit("FOrdGreaterThanEqual", boolean, x, y)
    def lor(x, y): return b.emit("LogicalOr", boolean, x, y)
    def land(x, y): return b.emit("LogicalAnd", boolean, x, y)
    def lerp(x, y, t): return b.ext(v4, GLSL_FMIX, x, y, b.construct(4, t, t, t, t))
    def comp(vec, i): return b.extract(vec, i)

    # The settings.
    packed = comp(v1, 0)
    top = floor_(mul(packed, b.const_float(1.0 / 128.0)))
    rest = sub(packed, mul(top, b.const_float(128.0)))
    mip_linear = floor_(mul(rest, b.const_float(1.0 / 64.0)))
    rest = sub(rest, mul(mip_linear, b.const_float(64.0)))
    min_linear = floor_(mul(rest, b.const_float(1.0 / 32.0)))
    rest = sub(rest, mul(min_linear, b.const_float(32.0)))
    mag_linear = floor_(mul(rest, b.const_float(1.0 / 16.0)))
    rest = sub(rest, mul(mag_linear, b.const_float(16.0)))
    mode_v = floor_(mul(rest, b.const_float(0.25)))
    mode_u = sub(rest, mul(mode_v, b.const_float(4.0)))

    # Which level, from how fast the coordinates change over the tile.
    size = b.emit("VectorShuffle", v2t, v0, v0, 2, 3)
    gx, gy = b.fmul(v2t, ddx, size), b.fmul(v2t, ddy, size)
    rho = fmax(b.ext(f, GLSL_LENGTH, gx), b.ext(f, GLSL_LENGTH, gy))
    lod = add(b.ext(f, GLSL_LOG2, fmax(rho, b.const_float(1e-8))), comp(v1, 1))
    minify = lt(zero, lod)
    lod = b.ext(f, GLSL_FCLAMP, lod, comp(v1, 2), fmin(comp(v1, 3), top))
    l0 = floor_(lod)
    l1 = fmin(add(l0, one), top)
    fraction = sub(lod, l0)
    fraction = sel(lt(half, mip_linear), fraction, b.ext(f, GLSL_STEP, half, fraction))
    linear = sel(minify, min_linear, mag_linear)

    def wrap(i, n, mode):
        """The texel number i (a whole number as a float) inside 0 to n - 1, and 1 if it was outside and the mode is the border."""
        repeated = sub(i, mul(n, floor_(b.fdiv(f, i, n))))
        n2 = mul(n, two)
        folded = sub(i, mul(n2, floor_(b.fdiv(f, i, n2))))
        mirrored = sel(lt(folded, n), folded, sub(sub(n2, one), folded))
        clamped = b.ext(f, GLSL_FCLAMP, i, zero, sub(n, one))
        index = sel(eq(mode, zero), repeated, sel(eq(mode, one), mirrored, clamped))
        outside = lor(lt(i, zero), ge(i, n))
        return index, sel(land(eq(mode, b.const_float(3.0)), outside), one, zero)

    border = v2
    image_value = image

    def tap(level):
        scale_down = b.ext(f, GLSL_EXP2, b.fsub(f, zero, level))
        wl = fmax(one, floor_(mul(comp(v0, 2), scale_down)))
        hl = fmax(one, floor_(mul(comp(v0, 3), scale_down)))
        ox, oy = floor_(mul(comp(v0, 0), scale_down)), floor_(mul(comp(v0, 1), scale_down))
        px, py = mul(comp(uv, 0), wl), mul(comp(uv, 1), hl)
        px = sub(px, mul(half, linear))
        py = sub(py, mul(half, linear))
        ix, iy = floor_(px), floor_(py)
        fx, fy = mul(sub(px, ix), linear), mul(sub(py, iy), linear)
        level_int = b.emit("ConvertFToS", b.int(), level)
        colors = []
        for dy in (0, 1):
            for dx in (0, 1):
                xi, outx = wrap(add(ix, b.const_float(float(dx))), wl, mode_u)
                yi, outy = wrap(add(iy, b.const_float(float(dy))), hl, mode_v)
                coord = b.emit("CompositeConstruct", iv2, b.emit("ConvertFToS", b.int(), add(ox, xi)), b.emit("ConvertFToS", b.int(), add(oy, yi)))
                texel = b.emit("ImageFetch", v4, image_value, coord, 2, level_int)
                outside = b.ext(f, GLSL_FMAX, outx, outy)
                colors.append(b.fadd(v4, texel, b.scale(4, b.fsub(v4, border, texel), outside)))
        top_row = lerp(colors[0], colors[1], fx)
        bottom_row = lerp(colors[2], colors[3], fx)
        return lerp(top_row, bottom_row, fy)

    return lerp(tap(l0), tap(l1), fraction)


def fragment_shader_masked(mask_offset, fog=False, cutout=True, blend=False, interlock=False):
    """
    The fragment shader of everything: the color of the vertex times the texture, where pixels that have the mask color
    are invisible if the mask is enabled (its fourth component is 1). This is how Blitz hides the background of images.
    With cutout=False the 3D one never discards, which leaves the depth test before the shader.
    With blend=True (3D only) the shader blends itself, for Dither 2: it reads what the color attachment holds (an input attachment,
    which VK_KHR_dynamic_rendering_local_read and VK_EXT_rasterization_order_attachment_access make possible while the draws
    that touch a pixel stay in order), mixes it with the color it makes as the fixed-function blend of the mode would (the
    mode is the specialization constants 1 to 5, see below), adds the noise of Dither to the result, and writes that without blending.

    #version 450
    layout(set = 0, binding = 0) uniform sampler2D tex;
    layout(push_constant) uniform Mask { layout(offset = mask_offset) vec4 mask; } pc;
    // In 3D (fog), the mask is read from the buffer of entities with layout(location = 6) flat in int inInstance instead.
    layout(location = 0) in vec2 inUV;
    layout(location = 1) in vec4 inColor;
    layout(location = 0) out vec4 outColor;
    void main() {
        vec4 t = texture(tex, inUV);
        vec3 d = abs(t.rgb - pc.mask.rgb);
        float same = step(max(max(d.x, d.y), d.z), 0.002) * pc.mask.w;
        outColor = inColor * vec4(t.rgb, t.a * (1.0 - same));
    }
    """
    b = Builder()
    if interlock:
        # Prototype: the target is a storage image read and written inside a pixel interlock (VK_EXT_fragment_shader_interlock).
        blend = True
        b.m.header.insert(1, Module.inst("Extension", string_words("SPV_EXT_fragment_shader_interlock")))
        b.m.header.insert(1, Module.inst("Capability", 5378))  # FragmentShaderPixelInterlockEXT
    if blend and not interlock:
        b.m.header.insert(1, Module.inst("Capability", 40))  # InputAttachment
    f, v2, v3, v4 = b.float(), b.vec(2), b.vec(3), b.vec(4)
    void, fn = b.void(), b.fn()
    c1 = b.const_float(1.0)
    epsilon = b.const_float(0.002)

    image = b.new_type("image", "TypeImage", f, 1, 0, 0, 0, 1, 0)
    sampled = b.new_type("sampled", "TypeSampledImage", image)
    mask_block = b.struct("mask", v4)
    if not fog:
        b.m.annotations += [
            Module.inst("MemberDecorate", mask_block, 0, DECORATION["Offset"], mask_offset),
            Module.inst("Decorate", mask_block, DECORATION["Block"]),
        ]
    push = None if fog else b.variable("PushConstant", mask_block)
    tex = b.variable("UniformConstant", sampled, [(DECORATION["DescriptorSet"], 0), (DECORATION["Binding"], 0)])
    in_uv = b.variable("Input", v2, [(DECORATION["Location"], 0)])
    in_color = b.variable("Input", v4, [(DECORATION["Location"], 1)])
    out_color = b.variable("Output", v4, [(DECORATION["Location"], 0)])
    interface = [in_uv, in_color, out_color]
    if fog:
        scene = declare_scene(b)
        in_depth = b.variable("Input", f, [(DECORATION["Location"], 2)])
        in_color_flat = b.variable("Input", v4, [(DECORATION["Location"], 3), (DECORATION["Flat"],)])
        in_spec = b.variable("Input", v3, [(DECORATION["Location"], 4)])
        in_spec_flat = b.variable("Input", v3, [(DECORATION["Location"], 5), (DECORATION["Flat"],)])
        in_mask = b.variable("Input", v4, [(DECORATION["Location"], 6), (DECORATION["Flat"],)])
        in_dir = b.variable("Input", v4, [(DECORATION["Location"], 7)])
        in_soft = b.variable("Input", v4, [(DECORATION["Location"], 8), (DECORATION["Flat"],)])
        in_views = [b.variable("Input", v4, [(DECORATION["Location"], 9 + k), (DECORATION["Flat"],)]) for k in range(3)]  # Views of atlases, see view_sample.
        in_frag = b.variable("Input", v4, [(DECORATION["BuiltIn"], BUILTIN_FRAG_COORD)])
        # The depth of what was drawn before the sprites, for SpriteDepthFade.
        depth_tex = b.variable("UniformConstant", sampled, [(DECORATION["DescriptorSet"], 3), (DECORATION["Binding"], 0)])
        if interlock:
            storage_image = b.new_type("storage_image", "TypeImage", f, 1, 0, 0, 0, 2, 4)  # 2D, no sampler, Rgba8
            target = b.variable("UniformConstant", storage_image, [(DECORATION["DescriptorSet"], 4), (DECORATION["Binding"], 0), (DECORATION["Coherent"],)])
        elif blend:
            # What the target holds at this pixel: dimension SubpassData, sampled 2 (read without a sampler), set 4, attachment 0.
            subpass = b.new_type("subpass", "TypeImage", f, 6, 0, 0, 0, 2, 0)
            target = b.variable("UniformConstant", subpass, [(DECORATION["DescriptorSet"], 4), (DECORATION["Binding"], 0), (DECORATION["InputAttachmentIndex"], 0)])
        interface += [in_depth, in_color_flat, in_spec, in_spec_flat, in_mask, in_dir, in_soft, in_frag, *in_views]

    main, label = b.m.id(), b.m.id()
    b.m.header.append(Module.inst("EntryPoint", 4, main, string_words("main"), *interface))
    b.m.header.append(Module.inst("ExecutionMode", main, 7))  # OriginUpperLeft
    if interlock:
        b.m.header.append(Module.inst("ExecutionMode", main, 5366))  # PixelInterlockOrderedEXT
    b.m.names.append(Module.inst("Name", main, string_words("main")))
    b.m.code += [Module.inst("Function", void, main, 0, fn), Module.inst("Label", label)]

    uv, color = b.load(v2, in_uv), b.load(v4, in_color)
    if fog:
        # A cube map is a sheet of three columns and two rows of faces, in the order of SetCubeFace: -X, +Z, +X, -Z, +Y, -Y.
        # The face is the one the biggest axis of the direction points to, which gives the same pictures that a cube texture would.
        look = b.load(v4, in_dir)
        inset = b.extract(look, 3)
        is_cube = b.ext(f, GLSL_STEP, b.const_float(1e-6), inset)
        lx, ly, lz = b.extract(look, 0), b.extract(look, 1), b.extract(look, 2)
        ax, ay, az = (b.ext(f, GLSL_FABS, v) for v in (lx, ly, lz))
        x_major = b.fmul(f, b.ext(f, GLSL_STEP, ay, ax), b.ext(f, GLSL_STEP, az, ax))
        y_major = b.fmul(f, b.fsub(f, c1, x_major), b.ext(f, GLSL_STEP, az, ay))
        z_major = b.fsub(f, b.fsub(f, c1, x_major), y_major)
        zero = b.const_float(0.0)
        px, py, pz = (b.ext(f, GLSL_STEP, zero, v) for v in (lx, ly, lz))  # 1 for the positive side.
        two = b.const_float(2.0)
        sign_x, sign_y, sign_z = (b.fsub(f, b.fmul(f, two, p), c1) for p in (px, py, pz))
        face = b.fadd(f, b.fadd(f, b.fmul(f, x_major, b.fmul(f, two, px)), b.fmul(f, z_major, b.fsub(f, b.const_float(3.0), b.fmul(f, two, pz)))), b.fmul(f, y_major, b.fsub(f, b.const_float(5.0), py)))
        neg_ly, neg_lz = b.fsub(f, zero, ly), b.fsub(f, zero, lz)
        sc = b.fadd(f, b.fadd(f, b.fmul(f, x_major, b.fmul(f, neg_lz, sign_x)), b.fmul(f, y_major, lx)), b.fmul(f, z_major, b.fmul(f, lx, sign_z)))
        tc = b.fadd(f, b.fadd(f, b.fmul(f, x_major, neg_ly), b.fmul(f, y_major, b.fmul(f, lz, sign_y))), b.fmul(f, z_major, neg_ly))
        major = b.fadd(f, b.fadd(f, b.fmul(f, x_major, ax), b.fmul(f, y_major, ay)), b.fmul(f, z_major, az))
        major = b.ext(f, GLSL_FMAX, major, b.const_float(1e-6))
        s_face = b.fmul(f, half_ := b.const_float(0.5), b.fadd(f, b.fdiv(f, sc, major), c1))
        t_face = b.fmul(f, half_, b.fadd(f, b.fdiv(f, tc, major), c1))
        s_face = b.ext(f, GLSL_FCLAMP, s_face, inset, b.fsub(f, c1, inset))
        t_face = b.ext(f, GLSL_FCLAMP, t_face, inset, b.fsub(f, c1, inset))
        row = b.ext(f, GLSL_STEP, b.const_float(3.0), face)
        column = b.fsub(f, face, b.fmul(f, b.const_float(3.0), row))
        sheet_uv = b.construct(2, b.fdiv(f, b.fadd(f, column, s_face), b.const_float(3.0)), b.fdiv(f, b.fadd(f, row, t_face), two))
        uv = b.fadd(v2, uv, b.scale(2, b.fsub(v2, sheet_uv, uv), is_cube))
    t = b.emit("ImageSampleImplicitLod", v4, b.load(sampled, tex), uv)
    if fog:
        # A view of an atlas samples its tile by hand: the hardware sampler could neither wrap nor mip inside a rectangle of an image. The
        # derivatives are taken before the branch, and the branch is the same for all pixels of a primitive, which is a draw of one entity.
        view0, view1, view2 = (b.load(v4, in_views[k]) for k in range(3))
        ddx, ddy = b.emit("DPdx", v2, uv), b.emit("DPdy", v2, uv)
        boolean = b.new_type("bool", "TypeBool")
        is_view = b.emit("FOrdGreaterThan", boolean, b.extract(view0, 3), b.const_float(0.0))
        entry_label = label
        view_label, merge_label = b.m.id(), b.m.id()
        b.m.code += [Module.inst("SelectionMerge", merge_label, 0), Module.inst("BranchConditional", is_view, view_label, merge_label), Module.inst("Label", view_label)]
        by_hand = view_sample(b, b.emit("Image", image, b.load(sampled, tex)), uv, ddx, ddy, view0, view1, view2)
        end_label = b.m.id()
        b.m.code += [Module.inst("Branch", end_label), Module.inst("Label", end_label), Module.inst("Branch", merge_label), Module.inst("Label", merge_label)]
        t = b.emit("Phi", v4, by_hand, end_label, t, entry_label)
    if fog:
        mask = b.load(v4, in_mask)
    else:
        mask = b.load(v4, b.access("PushConstant", v4, push, b.const_int(0)))
    if fog:
        # The third value of the mask asks for flat shading: the color of the first vertex of the triangle.
        flat = b.extract(mask, 2)
        color = b.fadd(v4, color, b.scale(4, b.fsub(v4, b.load(v4, in_color_flat), color), flat))
        spec = b.load(v3, in_spec)
        spec = b.fadd(v3, spec, b.scale(3, b.fsub(v3, b.load(v3, in_spec_flat), spec), flat))

    # In 3D the first three values of the mask mean other things, and the color that is not there is black.
    key = b.const_vec(3, 0.0) if fog else b.swizzle(mask, 3)
    diff = b.ext(v3, GLSL_FABS, b.fsub(v3, b.swizzle(t, 3), key))
    biggest = b.ext(f, GLSL_FMAX, b.ext(f, GLSL_FMAX, b.extract(diff, 0), b.extract(diff, 1)), b.extract(diff, 2))
    mask_w = b.extract(mask, 3)
    if fog:
        # In 3D the fourth value also says what the first texture does with the color: it is the cut-out flag plus twice the
        # blend, which is 0 for multiply (the usual), 1 for alpha, 2 add, 3 dot3, 4 twice multiply and 5 for no texture at all.
        # Textures that have no alpha channel have an alpha of 1, whatever a program drew into them: that is 16 more.
        no_alpha = b.ext(f, GLSL_STEP, b.const_float(15.5), mask_w)
        mask_w = b.fsub(f, mask_w, b.fmul(f, no_alpha, b.const_float(16.0)))
        blend_code = b.ext(f, GLSL_FLOOR, b.fmul(f, mask_w, b.const_float(0.5)))
        mask_w = b.fsub(f, mask_w, b.fmul(f, blend_code, b.const_float(2.0)))
        t = b.construct(4, b.extract(t, 0), b.extract(t, 1), b.extract(t, 2), b.ext(f, GLSL_FMAX, b.extract(t, 3), no_alpha))
    same = b.fmul(f, b.ext(f, GLSL_STEP, biggest, epsilon), mask_w)
    alpha = b.fmul(f, b.extract(t, 3), b.fsub(f, c1, same))
    visible = b.construct(4, b.extract(t, 0), b.extract(t, 1), b.extract(t, 2), alpha)
    result = b.fmul(v4, color, visible)
    if fog:
        # TextureBlend of the first texture, as the stages of Direct3D 7 do it: the texture is the first argument and the
        # color of the lighting the second. Each result is limited to what a color can be, as a stage is.
        zeros3, ones3 = b.const_vec(3, 0.0), b.const_vec(3, 1.0)
        col, texel = b.swizzle(color, 3), b.swizzle(t, 3)
        half3 = b.const_vec(3, 0.5)
        by_alpha = b.fadd(v3, col, b.scale(3, b.fsub(v3, texel, col), b.extract(t, 3)))
        added = b.ext(v3, GLSL_FCLAMP, b.fadd(v3, texel, col), zeros3, ones3)
        dotted = b.ext(f, GLSL_FCLAMP, b.fmul(f, b.dot(b.fsub(v3, texel, half3), b.fsub(v3, col, half3)), b.const_float(4.0)), b.const_float(0.0), c1)
        dot3 = b.construct(3, dotted, dotted, dotted)
        twice = b.ext(v3, GLSL_FCLAMP, b.scale(3, b.fmul(v3, texel, col), b.const_float(2.0)), zeros3, ones3)
        multiplied = b.swizzle(result, 3)

        def weight(code):
            return b.fsub(f, b.ext(f, GLSL_STEP, b.const_float(code - 0.5), blend_code), b.ext(f, GLSL_STEP, b.const_float(code + 0.5), blend_code))

        rgb3 = b.fmul(v3, multiplied, b.scale(3, ones3, weight(0)))
        for code, value in ((1, by_alpha), (2, added), (3, dot3), (4, twice), (5, col)):
            rgb3 = b.fadd(v3, rgb3, b.scale(3, value, weight(code)))
        # Without a texture the alpha of the color stays as it is, too.
        no_texture = weight(5)
        alpha_out = b.fadd(f, b.extract(result, 3), b.fmul(f, b.fsub(f, b.extract(color, 3), b.extract(result, 3)), no_texture))
        # Dot3 is written to all four channels, the alpha as well.
        alpha_out = b.fadd(f, alpha_out, b.fmul(f, b.fsub(f, dotted, alpha_out), weight(3)))
        result = b.construct(4, b.extract(rgb3, 0), b.extract(rgb3, 1), b.extract(rgb3, 2), alpha_out)
    if fog:
        # The highlight of lights is added to what the texture made of the color.
        lit_rgb = b.fadd(v3, b.swizzle(result, 3), spec)
        result = b.construct(4, b.extract(lit_rgb, 0), b.extract(lit_rgb, 1), b.extract(lit_rgb, 2), b.extract(result, 3))
    if fog and cutout:
        # Pixels that are less solid than the first value of the mask are not drawn at all, which is what makes
        # leaves and fences work with depth.
        boolean = b.new_type("bool", "TypeBool")
        cut = b.emit("FOrdLessThan", boolean, b.extract(result, 3), b.extract(mask, 0))
        kill_label, merge_label = b.m.id(), b.m.id()
        b.m.code += [
            Module.inst("SelectionMerge", merge_label, 0),
            Module.inst("BranchConditional", cut, kill_label, merge_label),
            Module.inst("Label", kill_label),
            Module.inst("Kill"),
            Module.inst("Label", merge_label),
        ]
    if fog and cutout:
        # Sprites with a depth fade (blended, so never in the solid variant) fade out where they get close to what is behind them: the distance between the depth
        # buffer, which holds what was drawn before the sprites, and the sprite itself, as a part of the distance asked for.
        #   if (soft.x > 0) { z(d) = ortho ? far - d * (far - near) : far * near / ((far - near) * d + near);
        #                     alpha *= clamp((z(texelFetch(depth, ivec2(gl_FragCoord.xy)).x) - z(gl_FragCoord.z)) / soft.x, 0, 1); }
        distance = b.extract(b.load(v4, in_soft), 0)
        soft_on = b.emit("FOrdGreaterThan", boolean, distance, b.const_float(1e-4))
        soft_label, soft_merge = b.m.id(), b.m.id()
        before_soft = merge_label
        b.m.code += [
            Module.inst("SelectionMerge", soft_merge, 0),
            Module.inst("BranchConditional", soft_on, soft_label, soft_merge),
            Module.inst("Label", soft_label),
        ]
        ivec2 = b.new_type("ivec2", "TypeVector", b.int(), 2)
        fetched = b.emit("Image", image, b.load(sampled, depth_tex))
        frag = b.load(v4, in_frag)
        pixel = b.emit("CompositeConstruct", ivec2, b.emit("ConvertFToS", b.int(), b.extract(frag, 0)), b.emit("ConvertFToS", b.int(), b.extract(frag, 1)))
        scene_depth = b.extract(b.emit("ImageFetch", v4, fetched, pixel), 0)
        projection = b.load(v4, b.access("Uniform", v4, scene, b.const_int(11)))
        near, far, ortho = b.extract(projection, 0), b.extract(projection, 1), b.extract(projection, 2)
        span = b.fsub(f, far, near)

        def linear(d):
            perspective = b.fdiv(f, b.fmul(f, far, near), b.fadd(f, b.fmul(f, span, d), near))
            orthographic = b.fsub(f, far, b.fmul(f, d, span))
            return b.fadd(f, perspective, b.fmul(f, b.fsub(f, orthographic, perspective), ortho))

        gap = b.fsub(f, linear(scene_depth), linear(b.extract(frag, 2)))
        fade = b.ext(f, GLSL_FCLAMP, b.fdiv(f, gap, distance), b.const_float(0.0), c1)
        b.m.code += [Module.inst("Branch", soft_merge), Module.inst("Label", soft_merge)]
        fade = b.emit("Phi", f, fade, soft_label, c1, before_soft)
        result = b.construct(4, b.extract(result, 0), b.extract(result, 1), b.extract(result, 2), b.fmul(f, b.extract(result, 3), fade))
    if fog:
        # Linear between the near and far distance (x and y), if it is on (z). This is per pixel, so that it also
        # works for things that are much bigger than they look.
        parameters = b.load(v4, b.access("Uniform", v4, scene, b.const_int(4)))
        fog_color = b.swizzle(b.load(v4, b.access("Uniform", v4, scene, b.const_int(5))), 3)
        span = b.ext(f, GLSL_FMAX, b.fsub(f, b.extract(parameters, 1), b.extract(parameters, 0)), b.const_float(1e-4))
        amount = b.fmul(f, b.ext(f, GLSL_FCLAMP, b.fdiv(f, b.fsub(f, b.load(f, in_depth), b.extract(parameters, 0)), span), b.const_float(0.0), c1), b.extract(parameters, 2))
        # The second value of the mask turns the fog off for what is drawn on top of what already has it.
        amount = b.fmul(f, amount, b.fsub(f, c1, b.extract(mask, 1)))
        rgb = b.swizzle(result, 3)
        rgb = b.fadd(v3, rgb, b.scale(3, b.fsub(v3, fog_color, rgb), amount))
        result = b.construct(4, b.extract(rgb, 0), b.extract(rgb, 1), b.extract(rgb, 2), b.extract(result, 3))
        # Dither: a specialization constant (id 0, the pipelines are made again when Dither changes), so that the code is not
        # in the pipeline at all when it is off. The fourth value of the projection is 1 plus the shift of the noise of this frame.
        # The color gets temporal Interleaved Gradient Noise (Jimenez, 2014) of less than half a step of the 8 bit target
        # before it is rounded, so that lighting, fog and blending are not bands but a pattern, and exact colors stay.
        #   layout(constant_id = 0) const bool dither = false;
        #   if (dither) { vec2 xy = floor(gl_FragCoord.xy) + vec2(scene.projection.w - 1.0);
        #                 rgb += (fract(52.9829189 * fract(dot(xy, vec2(0.06711056, 0.00583715)))) - 0.5) / 255.0 * (not exact); }
        # The shader that blends itself dithers what it blends instead, always, as it is only used when Dither is 2.
        def noise_offset():
            w = b.extract(b.load(v4, b.access("Uniform", v4, scene, b.const_int(11))), 3)
            frag = b.load(v4, in_frag)
            shift = b.fsub(f, w, c1)
            px = b.fadd(f, b.ext(f, GLSL_FLOOR, b.extract(frag, 0)), shift)
            py = b.fadd(f, b.ext(f, GLSL_FLOOR, b.extract(frag, 1)), shift)
            along = b.fadd(f, b.fmul(f, px, b.const_float(0.06711056)), b.fmul(f, py, b.const_float(0.00583715)))
            noise = b.ext(f, GLSL_FRACT, b.fmul(f, b.ext(f, GLSL_FRACT, along), b.const_float(52.9829189)))
            return b.fmul(f, b.fsub(f, noise, b.const_float(0.5)), b.const_float(1.0 / 255.0))

        def noise_for(color):
            # A channel that the 8 bit target shows exactly gets no noise: a GPU may convert with a little error, which turns the
            # lowest noise (half a step below) into a step below the color, in some pixels. Within 1/64 of a step counts as exact.
            #   vec3 steps = rgb * 255.0;  noise * step(1.0 / 64.0, abs(steps - floor(steps + 0.5)));
            steps = b.fmul(v3, color, b.const_vec(3, 255.0))
            away = b.ext(v3, GLSL_FABS, b.fsub(v3, steps, b.ext(v3, GLSL_FLOOR, b.fadd(v3, steps, b.const_vec(3, 0.5)))))
            inexact = b.ext(v3, GLSL_STEP, b.const_vec(3, 1.0 / 64.0), away)
            return b.fmul(v3, b.scale(3, b.const_vec(3, 1.0), noise_offset()), inexact)

        if blend:
            # The blend of the fixed-function pipeline, with the factors as specialization constants (ids 1 to 5). The factor of
            # the color that is drawn is a * source_alpha + b * destination, and the factor of what is there is c + d * source_alpha
            # + e * drawn color. The alpha is always as with blending by alpha, as in the pipelines. The modes are
            #   by alpha  a=1 b=0 c=1 d=-1 e=0      multiply        a=0 b=1 c=0 d=0 e=0
            #   add       a=1 b=0 c=1 d=0  e=0      multiply by 2   a=0 b=1 c=0 d=0 e=1
            #   layout(input_attachment_index = 0, set = 4, binding = 0) uniform subpassInput target;
            #   vec4 there = subpassLoad(target);
            #   rgb = rgb * (fa * a + fb * there.rgb) + there.rgb * (fc + fd * a + fe * rgb);  alpha = a + there.a * (1 - a);
            #   rgb += noise;
            ivec2 = b.new_type("ivec2", "TypeVector", b.int(), 2)
            zero_i = b.const_int(0)
            origin = b.m.id()
            b.m.types.append(Module.inst("ConstantComposite", ivec2, origin, zero_i, zero_i))
            factors = []
            for number, default in enumerate((1.0, 0.0, 1.0, -1.0, 0.0), start=1):
                constant = b.m.id()
                b.m.types.append(Module.inst("SpecConstant", f, constant, float_bits(default)))
                b.m.annotations.append(Module.inst("Decorate", constant, DECORATION["SpecId"], number))
                factors.append(constant)
            fa, fb, fc, fd, fe = factors
            if interlock:
                at = b.load(v4, in_frag)
                pixel = b.emit("CompositeConstruct", ivec2, b.emit("ConvertFToS", b.int(), b.extract(at, 0)), b.emit("ConvertFToS", b.int(), b.extract(at, 1)))
                b.m.code.append(Module.inst("BeginInvocationInterlockEXT"))
                there = b.emit("ImageRead", v4, b.load(storage_image, target), pixel)
            else:
                there = b.emit("ImageRead", v4, b.load(subpass, target), origin)
            there_rgb = b.swizzle(there, 3)
            alpha = b.extract(result, 3)
            drawn_factor = b.fadd(v3, b.scale(3, there_rgb, fb), b.construct(3, *([b.fmul(f, fa, alpha)] * 3)))
            there_factor = b.fadd(v3, b.scale(3, rgb, fe), b.construct(3, *([b.fadd(f, fc, b.fmul(f, fd, alpha))] * 3)))
            blended = b.fadd(v3, b.emit("FMul", v3, rgb, drawn_factor), b.emit("FMul", v3, there_rgb, there_factor))
            blended = b.fadd(v3, blended, noise_for(blended))
            blended_alpha = b.fadd(f, alpha, b.fmul(f, b.extract(there, 3), b.fsub(f, c1, alpha)))
            result = b.construct(4, b.extract(blended, 0), b.extract(blended, 1), b.extract(blended, 2), blended_alpha)
        else:
            boolean = b.new_type("bool", "TypeBool")
            dither_on = b.m.id()
            b.m.types.append(Module.inst("SpecConstantTrue", boolean, dither_on))
            b.m.annotations.append(Module.inst("Decorate", dither_on, DECORATION["SpecId"], 0))
            before_dither, dither_label, dither_merge = b.m.id(), b.m.id(), b.m.id()
            b.m.code += [
                Module.inst("Branch", before_dither),
                Module.inst("Label", before_dither),
                Module.inst("SelectionMerge", dither_merge, 0),
                Module.inst("BranchConditional", dither_on, dither_label, dither_merge),
                Module.inst("Label", dither_label),
            ]
            dithered = b.fadd(v3, rgb, noise_for(rgb))
            b.m.code += [Module.inst("Branch", dither_merge), Module.inst("Label", dither_merge)]
            rgb = b.emit("Phi", v3, dithered, dither_label, rgb, before_dither)
            result = b.construct(4, b.extract(rgb, 0), b.extract(rgb, 1), b.extract(rgb, 2), b.extract(result, 3))
    if interlock:
        b.m.code.append(Module.inst("ImageWrite", b.load(storage_image, target), pixel, result))
        b.m.code.append(Module.inst("EndInvocationInterlockEXT"))
    else:
        b.store(out_color, result)
    b.m.code += [Module.inst("Return"), Module.inst("FunctionEnd")]
    return b.m.assemble()


def vertex_shader_fullscreen():
    """
    One triangle that covers the whole target, for passes over an image.

    #version 450
    layout(location = 0) out vec2 outUV;
    void main() {
        float i = float(gl_VertexIndex);
        outUV = vec2(i * (2.0 - i) * 2.0, i * (i - 1.0)); // (0, 0), (2, 0), (0, 2)
        gl_Position = vec4(outUV * 2.0 - 1.0, 0.0, 1.0);
    }
    """
    b = Builder()
    f, v2, v4, i32 = b.float(), b.vec(2), b.vec(4), b.int()
    void, fn = b.void(), b.fn()
    c0, c1, c2 = b.const_float(0.0), b.const_float(1.0), b.const_float(2.0)
    block = b.struct("pervertex", v4)
    b.m.annotations += [
        Module.inst("MemberDecorate", block, 0, DECORATION["BuiltIn"], 0),   # Position
        Module.inst("Decorate", block, DECORATION["Block"]),
    ]
    vertex_index = b.variable("Input", i32, [(DECORATION["BuiltIn"], 42)])
    out_uv = b.variable("Output", v2, [(DECORATION["Location"], 0)])
    per_vertex = b.variable("Output", block)
    main, label = b.m.id(), b.m.id()
    b.m.header.append(Module.inst("EntryPoint", 0, main, string_words("main"), vertex_index, out_uv, per_vertex))
    b.m.names.append(Module.inst("Name", main, string_words("main")))
    b.m.code += [Module.inst("Function", void, main, 0, fn), Module.inst("Label", label)]

    index = b.emit("ConvertSToF", f, b.load(i32, vertex_index))
    x = b.fmul(f, b.fmul(f, index, b.fsub(f, c2, index)), c2)
    y = b.fmul(f, index, b.fsub(f, index, c1))
    uv = b.construct(2, x, y)
    b.store(out_uv, uv)
    clip = b.fsub(v2, b.fmul(v2, uv, b.const_vec(2, 2.0)), b.const_vec(2, 1.0))
    position = b.construct(4, b.extract(clip, 0), b.extract(clip, 1), c0, c1)
    b.store(b.access("Output", v4, per_vertex, b.const_int(0)), position)
    b.m.code += [Module.inst("Return"), Module.inst("FunctionEnd")]
    return b.m.assemble()


def fragment_shader_gamma():
    """
    Shows an image through the gamma tables, which are in a uniform buffer with a row for each of the 256 steps and the
    new value of red, green and blue (from 0 to 1) in the row. The fourth value of the first row is 1 when Dither is on:
    the result then gets temporal Interleaved Gradient Noise (Jimenez, 2014) of up to half a step of the 8 bit picture
    added, so that the steps that rounding makes are not lines but a pattern that the eye averages. The pattern moves
    every frame: the push constant is 5.588238 * float(frame % 64), added to both coordinates of the pixel.

    #version 450
    layout(set = 0, binding = 0) uniform sampler2D tex;
    layout(set = 1, binding = 0) uniform Gamma { vec4 table[256]; } gamma;
    layout(push_constant) uniform Dither { float shift; } pc;
    layout(location = 0) in vec2 inUV;
    layout(location = 0) out vec4 outColor;
    void main() {
        vec3 step = floor(texture(tex, inUV).rgb * 255.0 + 0.5);
        vec3 color = vec3(gamma.table[int(step.r)].r, gamma.table[int(step.g)].g, gamma.table[int(step.b)].b);
        vec2 xy = floor(gl_FragCoord.xy) + vec2(pc.shift);
        float noise = fract(52.9829189 * fract(dot(xy, vec2(0.06711056, 0.00583715))));
        outColor = vec4(color + (noise - 0.5) / 255.0 * gamma.table[0].w, 1.0);
    }
    """
    b = Builder()
    f, v2, v3, v4, i32 = b.float(), b.vec(2), b.vec(3), b.vec(4), b.int()
    void, fn = b.void(), b.fn()
    image = b.new_type("image", "TypeImage", f, 1, 0, 0, 0, 1, 0)
    sampled = b.new_type("sampled", "TypeSampledImage", image)
    table = b.array(v4, 256, "table")
    block = b.struct("gamma", table)
    b.m.annotations += [
        Module.inst("Decorate", table, DECORATION["ArrayStride"], 16),
        Module.inst("MemberDecorate", block, 0, DECORATION["Offset"], 0),
        Module.inst("Decorate", block, DECORATION["Block"]),
    ]
    shift_block = b.struct("dither", f)
    b.m.annotations += [
        Module.inst("MemberDecorate", shift_block, 0, DECORATION["Offset"], 0),
        Module.inst("Decorate", shift_block, DECORATION["Block"]),
    ]
    shift_push = b.variable("PushConstant", shift_block)
    tex = b.variable("UniformConstant", sampled, [(DECORATION["DescriptorSet"], 0), (DECORATION["Binding"], 0)])
    gamma = b.variable("Uniform", block, [(DECORATION["DescriptorSet"], 1), (DECORATION["Binding"], 0)])
    in_uv = b.variable("Input", v2, [(DECORATION["Location"], 0)])
    out_color = b.variable("Output", v4, [(DECORATION["Location"], 0)])
    in_frag = b.variable("Input", v4, [(DECORATION["BuiltIn"], BUILTIN_FRAG_COORD)])
    main, label = b.m.id(), b.m.id()
    b.m.header.append(Module.inst("EntryPoint", 4, main, string_words("main"), in_uv, out_color, in_frag))
    b.m.header.append(Module.inst("ExecutionMode", main, 7))  # OriginUpperLeft
    b.m.names.append(Module.inst("Name", main, string_words("main")))
    b.m.code += [Module.inst("Function", void, main, 0, fn), Module.inst("Label", label)]

    shown = b.swizzle(b.emit("ImageSampleImplicitLod", v4, b.load(sampled, tex), b.load(v2, in_uv)), 3)
    steps = b.ext(v3, GLSL_FLOOR, b.fadd(v3, b.fmul(v3, shown, b.const_vec(3, 255.0)), b.const_vec(3, 0.5)))
    channels = []
    for channel in range(3):
        step = b.emit("ConvertFToS", i32, b.extract(steps, channel))
        row = b.load(v4, b.access("Uniform", v4, gamma, b.const_int(0), step))
        channels.append(b.extract(row, channel))
    # Temporal Interleaved Gradient Noise of the pixel: fract(52.9829189 * fract(dot(pixel + shift, (0.06711056, 0.00583715)))).
    frag = b.load(v4, in_frag)
    shift = b.load(f, b.access("PushConstant", f, shift_push, b.const_int(0)))
    px = b.fadd(f, b.ext(f, GLSL_FLOOR, b.extract(frag, 0)), shift)
    py = b.fadd(f, b.ext(f, GLSL_FLOOR, b.extract(frag, 1)), shift)
    along = b.fadd(f, b.fmul(f, px, b.const_float(0.06711056)), b.fmul(f, py, b.const_float(0.00583715)))
    noise = b.ext(f, GLSL_FRACT, b.fmul(f, b.ext(f, GLSL_FRACT, along), b.const_float(52.9829189)))
    enabled = b.extract(b.load(v4, b.access("Uniform", v4, gamma, b.const_int(0), b.const_int(0))), 3)
    offset = b.fmul(f, b.fmul(f, b.fsub(f, noise, b.const_float(0.5)), b.const_float(1.0 / 255.0)), enabled)
    channels = [b.fadd(f, channel, offset) for channel in channels]
    b.store(out_color, b.construct(4, *channels, b.const_float(1.0)))
    b.m.code += [Module.inst("Return"), Module.inst("FunctionEnd")]
    return b.m.assemble()


def compute_shader_cull():
    """
    Decides for chunks of 64 clusters (runs of triangles of a big mesh, with a sphere around them) of draws whether they are
    inside of what the camera sees, and writes the command that draws each: a count of 0 instances when not. The commands are
    then drawn with a single indirect call for each draw, see record_scene. The planes are the ones of the view in camera
    relative space, like the matrices of the entities are.

    #version 450
    layout(local_size_x = 64) in;
    struct Cluster { vec4 sphere; ivec4 range; vec4 cone; }; // Center and radius, in the space of the mesh. First index and number of indices. Axis of the normals of the faces and the cutoff (more than 1: no cone).
    struct Group { ivec4 draw; vec4 growth; };               // Number of the draw, first cluster, clusters, first command. x: how much the matrix of the draw can lengthen a vector, y: 1 when the faces turned away can be left out (the matrix only turns and scales, and the camera looks from a point).
    struct Command { int indexCount, instanceCount, firstIndex, vertexOffset, firstInstance; };
    struct Entity { vec4 model0, model1, model2; vec4 rest[6]; };
    layout(set = 0, binding = 0) readonly buffer Entities { Entity entities[]; };
    layout(set = 1, binding = 0) readonly buffer Clusters { Cluster clusters[]; };
    layout(set = 1, binding = 1) readonly buffer Groups { Group groups[]; };
    layout(set = 1, binding = 2) buffer Commands { Command commands[]; };
    layout(push_constant) uniform Push { vec4 planes[6]; ivec4 base; } push;   // base.x: the first group of this dispatch.
    void main() {
        Group group = groups[push.base.x + gl_WorkGroupID.x];
        int lane = int(gl_LocalInvocationID.x);
        bool valid = lane < group.draw.z;
        Cluster c = clusters[group.draw.y + (valid ? lane : 0)];
        Entity e = entities[group.draw.x];
        vec4 p = vec4(c.sphere.xyz, 1.0);
        vec3 center = vec3(dot(e.model0, p), dot(e.model1, p), dot(e.model2, p));
        float radius = c.sphere.w * group.growth.x * 1.001 + 0.01 + 1e-5 * (abs(center.x) + abs(center.y) + abs(center.z));
        float inside = dot(push.planes[0].xyz, center) + push.planes[0].w;
        for (int i = 1; i < 6; i++) inside = min(inside, dot(push.planes[i].xyz, center) + push.planes[i].w);
        int slot = valid ? group.draw.w + lane : 0;    // Command 0 is where the lanes that have no cluster write to.
        vec3 axis = vec3(dot(e.model0.xyz, c.cone.xyz), dot(e.model1.xyz, c.cone.xyz), dot(e.model2.xyz, c.cone.xyz));
        bool away = group.growth.y > 0.5 && dot(center, axis) >= (c.cone.w * length(center) + radius) * length(axis);   // The camera is at the origin.
        commands[slot] = Command(c.range.y, (inside + radius >= 0.0 && !away) ? 1 : 0, c.range.x, 0, group.draw.x);
    }
    """
    b = Builder()
    f, v3, v4, i32, iv4 = b.float(), b.vec(3), b.vec(4), b.int(), b.new_type(("ivec", 4), "TypeVector", b.int(), 4)
    void, fn = b.void(), b.fn()
    iv3 = b.new_type(("ivec", 3), "TypeVector", b.int(), 3)
    boolean = b.new_type("bool", "TypeBool")
    zero, one = b.const_int(0), b.const_int(1)

    def buffer(name, set_index, binding, element, stride, writable):
        array = b.new_type(("runtime", name), "TypeRuntimeArray", element)
        b.m.annotations.append(Module.inst("Decorate", array, DECORATION["ArrayStride"], stride))
        block = b.struct(name, array)
        b.m.annotations += [Module.inst("MemberDecorate", block, 0, DECORATION["Offset"], 0), Module.inst("Decorate", block, DECORATION["BufferBlock"])]
        if not writable:
            b.m.annotations.append(Module.inst("MemberDecorate", block, 0, DECORATION["NonWritable"]))
        return b.variable("Uniform", block, [(DECORATION["DescriptorSet"], set_index), (DECORATION["Binding"], binding)])

    entities, _ = declare_entities(b, 0)
    cluster = b.struct("cluster", v4, iv4, v4)
    group = b.struct("group", iv4, v4)
    command = b.struct("command", i32, i32, i32, i32, i32)
    b.m.annotations += [
        Module.inst("MemberDecorate", cluster, 0, DECORATION["Offset"], 0), Module.inst("MemberDecorate", cluster, 1, DECORATION["Offset"], 16), Module.inst("MemberDecorate", cluster, 2, DECORATION["Offset"], 32),
        Module.inst("MemberDecorate", group, 0, DECORATION["Offset"], 0), Module.inst("MemberDecorate", group, 1, DECORATION["Offset"], 16),
    ]
    for index in range(5):
        b.m.annotations.append(Module.inst("MemberDecorate", command, index, DECORATION["Offset"], index * 4))
    clusters = buffer("clusters", 1, 0, cluster, 48, False)
    groups = buffer("groups", 1, 1, group, 32, False)
    commands = buffer("commands", 1, 2, command, 20, True)

    planes = b.array(v4, 6, "planes")
    b.m.annotations.append(Module.inst("Decorate", planes, DECORATION["ArrayStride"], 16))
    push = b.struct("push", planes, iv4)
    b.m.annotations += [
        Module.inst("MemberDecorate", push, 0, DECORATION["Offset"], 0),
        Module.inst("MemberDecorate", push, 1, DECORATION["Offset"], 96),
        Module.inst("Decorate", push, DECORATION["Block"]),
    ]
    push_var = b.variable("PushConstant", push)
    workgroup = b.variable("Input", iv3, [(DECORATION["BuiltIn"], BUILTIN_WORKGROUP_ID)])
    local = b.variable("Input", iv3, [(DECORATION["BuiltIn"], BUILTIN_LOCAL_INVOCATION_ID)])

    main, label = b.m.id(), b.m.id()
    b.m.header.append(Module.inst("EntryPoint", EXECUTION_MODEL_GLCOMPUTE, main, string_words("main"), workgroup, local))
    b.m.header.append(Module.inst("ExecutionMode", main, EXECUTION_MODE_LOCAL_SIZE, 64, 1, 1))
    b.m.names.append(Module.inst("Name", main, string_words("main")))
    b.m.code += [Module.inst("Function", void, main, 0, fn), Module.inst("Label", label)]

    def int_member(vector, index):
        return b.emit("CompositeExtract", i32, vector, index)

    base = b.load(iv4, b.access("PushConstant", iv4, push_var, one))
    group_id = b.emit("IAdd", i32, int_member(base, 0), b.emit("CompositeExtract", i32, b.load(iv3, workgroup), 0))
    lane = b.emit("CompositeExtract", i32, b.load(iv3, local), 0)
    draw = b.load(iv4, b.access("Uniform", iv4, groups, zero, group_id, zero))
    growth_values = b.load(v4, b.access("Uniform", v4, groups, zero, group_id, one))
    growth, turned = b.extract(growth_values, 0), b.extract(growth_values, 1)
    entity_index, first_cluster, cluster_count, first_command = (int_member(draw, k) for k in range(4))
    valid = b.emit("SLessThan", boolean, lane, cluster_count)
    cluster_index = b.emit("IAdd", i32, first_cluster, b.emit("Select", i32, valid, lane, zero))
    sphere = b.load(v4, b.access("Uniform", v4, clusters, zero, cluster_index, zero))
    range_ = b.load(iv4, b.access("Uniform", iv4, clusters, zero, cluster_index, one))
    cone = b.load(v4, b.access("Uniform", v4, clusters, zero, cluster_index, b.const_int(2)))
    p = b.construct(4, b.extract(sphere, 0), b.extract(sphere, 1), b.extract(sphere, 2), b.const_float(1.0))
    center = b.construct(3, *(b.dot(entity_member(b, entities, entity_index, row), p) for row in range(3)))
    magnitude = b.fadd(f, b.fadd(f, b.ext(f, GLSL_FABS, b.extract(center, 0)), b.ext(f, GLSL_FABS, b.extract(center, 1))), b.ext(f, GLSL_FABS, b.extract(center, 2)))
    radius = b.fadd(f, b.fadd(f, b.fmul(f, b.fmul(f, b.extract(sphere, 3), growth), b.const_float(1.001)), b.const_float(0.01)), b.fmul(f, b.const_float(1e-5), magnitude))
    inside = None
    for plane in range(6):
        pl = b.load(v4, b.access("PushConstant", v4, push_var, zero, b.const_int(plane)))
        distance = b.fadd(f, b.dot(b.swizzle(pl, 3), center), b.extract(pl, 3))
        inside = distance if inside is None else b.ext(f, GLSL_FMIN, inside, distance)
    visible = b.emit("FOrdGreaterThanEqual", boolean, b.fadd(f, inside, radius), b.const_float(0.0))
    direction = b.construct(4, b.extract(cone, 0), b.extract(cone, 1), b.extract(cone, 2), b.const_float(0.0))
    axis = b.construct(3, *(b.dot(entity_member(b, entities, entity_index, row), direction) for row in range(3)))
    reach = b.fmul(f, b.fadd(f, b.fmul(f, b.extract(cone, 3), b.ext(f, GLSL_LENGTH, center)), radius), b.ext(f, GLSL_LENGTH, axis))
    away = b.emit("LogicalAnd", boolean, b.emit("FOrdLessThan", boolean, b.const_float(0.5), turned), b.emit("FOrdGreaterThanEqual", boolean, b.dot(center, axis), reach))
    visible = b.emit("LogicalAnd", boolean, visible, b.emit("LogicalNot", boolean, away))
    slot = b.emit("Select", i32, valid, b.emit("IAdd", i32, first_command, lane), zero)
    values = (int_member(range_, 1), b.emit("Select", i32, visible, one, zero), int_member(range_, 0), zero, entity_index)
    for index, value in enumerate(values):
        b.store(b.access("Uniform", i32, commands, zero, slot, b.const_int(index)), value)
    b.m.code += [Module.inst("Return"), Module.inst("FunctionEnd")]
    return b.m.assemble()


def emit(name, words, out):
    out.write("static const unsigned int %s[] = {\n" % name)
    for index in range(0, len(words), 8):
        out.write("\t" + ", ".join("0x%08x" % w for w in words[index:index + 8]) + ",\n")
    out.write("};\n")


with open(sys.argv[1], "w", newline="\n") as out:
    out.write("// Generated by tools/generate_shaders.py, do not edit.\n")
    emit("bb_shader_vertex", vertex_shader(), out)
    emit("bb_shader_fragment", fragment_shader_masked(16), out)
    emit("bb_shader_vertex_3d", vertex_shader_3d(), out)
    emit("bb_shader_fragment_3d", fragment_shader_masked(96, fog=True), out)
    emit("bb_shader_fragment_3d_solid", fragment_shader_masked(96, fog=True, cutout=False), out)
    emit("bb_shader_fragment_3d_blend", fragment_shader_masked(96, fog=True, blend=True), out)
    emit("bb_shader_fragment_3d_blend_interlock", fragment_shader_masked(96, fog=True, interlock=True), out)
    emit("bb_shader_vertex_fullscreen", vertex_shader_fullscreen(), out)
    emit("bb_shader_fragment_gamma", fragment_shader_gamma(), out)
    emit("bb_shader_compute_cull", compute_shader_cull(), out)
